uint8_t qdos_small_font_row(char ch, int row) {
	const unsigned char c = (unsigned char)ch;
	if (row < 0 || row >= QDOS_SMALL_FONT_H || c < FIRST_CHAR || c > LAST_CHAR)
		return 0;

	return GLYPHS[c - FIRST_CHAR][row];
}
